def choose_move(observation):
    px, py = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    obstacles = set(map(tuple, observation.get('obstacles', [])))
    resources = observation.get('resources', [])
    opponent = observation.get('opponent_position', None)

    def in_bounds(x, y):
        return 0 <= x < width and 0 <= y < height

    moves = [ (0,1), (0,-1), (1,0), (-1,0) ]
    for dx, dy in moves:
        nx, ny = px + dx, py + dy
        if in_bounds(nx, ny) and (nx, ny) not in obstacles:
            # Prefer move towards closest resource
            if resources:
                rx, ry = min(resources, key=lambda r: abs(r['x']-nx) + abs(r['y']-ny))
                if abs(rx - nx) + abs(ry - ny) < abs(rx - px) + abs(ry - py):
                    return [dx, dy]
            # Else, move towards opponent if present
            if opponent:
                if abs(opponent[0] - nx) + abs(opponent[1] - ny) < abs(opponent[0] - px) + abs(opponent[1] - py):
                    return [dx, dy]
            # Else, default move
            return [dx, dy]
    return [0,0]
